import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int length = scanner.nextInt();
        String str = scanner.next();
        boolean inParentheses = false;
        StringBuilder segmentBuilder = new StringBuilder();
        int maxOutsideSize = 0;
        int insideWordsCount = 0;
        for (int i = 0; i < length; i++) {
            char ch = str.charAt(i);
            if (ch == '(') {
                if (!inParentheses) {
                    String[] outsideParts = segmentBuilder.toString().split("_");
                    for (String part : outsideParts) {
                        maxOutsideSize = Math.max(maxOutsideSize, part.length());
                    }
                }
                inParentheses = true;
                segmentBuilder = new StringBuilder();
            } else if (ch == ')') {
                inParentheses = false;
                String[] insideParts = segmentBuilder.toString().split("_");
                for (String part : insideParts) {
                    if (!part.isEmpty()) {
                        insideWordsCount++;
                    }
                }
                segmentBuilder = new StringBuilder();
            } else {
                segmentBuilder.append(ch);
            }
        }
        String[] outsideRemaining = segmentBuilder.toString().split("_");
        for (String part : outsideRemaining) {
            maxOutsideSize = Math.max(maxOutsideSize, part.length());
        }
        System.out.println(maxOutsideSize + " " + insideWordsCount);
    }
}
